-- Restore the prices that belong to Luna Healthy's original catalog.
-- Discounted prices remain optional through product_prices.compare_at_price_egp.
update public.product_prices
set
  price_egp = case id
    when '30000000-0000-0000-0000-000000000001'::uuid then 950
    when '30000000-0000-0000-0000-000000000002'::uuid then 1550
    when '30000000-0000-0000-0000-000000000003'::uuid then 830
    when '30000000-0000-0000-0000-000000000004'::uuid then 1350
    when '30000000-0000-0000-0000-000000000005'::uuid then 900
    when '30000000-0000-0000-0000-000000000006'::uuid then 1450
    when '30000000-0000-0000-0000-000000000007'::uuid then 800
    when '30000000-0000-0000-0000-000000000008'::uuid then 1300
    when '30000000-0000-0000-0000-000000000009'::uuid then 900
    when '30000000-0000-0000-0000-000000000010'::uuid then 1450
    when '30000000-0000-0000-0000-000000000011'::uuid then 550
    when '30000000-0000-0000-0000-000000000012'::uuid then 500
    when '30000000-0000-0000-0000-000000000013'::uuid then 480
    when '30000000-0000-0000-0000-000000000014'::uuid then 530
    when '30000000-0000-0000-0000-000000000015'::uuid then 500
    when '30000000-0000-0000-0000-000000000016'::uuid then 520
    when '30000000-0000-0000-0000-000000000017'::uuid then 140
    when '30000000-0000-0000-0000-000000000018'::uuid then 170
    when '30000000-0000-0000-0000-000000000019'::uuid then 85
    when '30000000-0000-0000-0000-000000000020'::uuid then 140
    else price_egp
  end,
  compare_at_price_egp = null,
  is_active = true
where id between '30000000-0000-0000-0000-000000000001'::uuid
  and '30000000-0000-0000-0000-000000000020'::uuid;
